/* ── Player View — Cyber Supply-Chain Console ────────── */

@layer components {
  .player-layout {
    display: grid;
    grid-template-rows: auto auto 1fr auto;
    height: 100dvh;
    overflow: hidden;
    background: var(--color-background);
    position: relative;
    z-index: 0;
  }
  .player-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-md);
    padding: var(--spacing-sm) var(--spacing-lg);
    background: var(--glass-bg), var(--color-card);
    backdrop-filter: blur(var(--glass-blur));
    -webkit-backdrop-filter: blur(var(--glass-blur));
    border-bottom: 1px solid var(--color-primary);
    box-shadow: var(--glass-shadow), var(--glow-sm);
    position: relative;
  }
  .player-header::after {
    content: "";
    position: absolute;
    inset: 0;
    background: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      oklch(0% 0 0 / 8%) 2px,
      oklch(0% 0 0 / 8%) 4px
    );
    pointer-events: none;
  }
  .player-header__title {
    font-family: var(--font-mono);
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-primary);
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }
  .player-header > .stress-bar {
    flex: 1;
  }
  .player-header__clocks {
    display: flex;
    gap: var(--spacing-lg);
    align-items: center;
  }
  .player-footer {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    padding: var(--spacing-xs) var(--spacing-lg);
    border-top: 1px solid var(--color-border);
    background: var(--color-card);
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  .player-footer__group {
    display: flex;
    gap: var(--spacing-sm);
    align-items: center;
  }
  .player-main {
    overflow-y: auto;
    padding: var(--spacing-md) var(--spacing-lg);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-lg);
    background: var(--color-background);
  }
  .player-main__columns {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-md);
  }
  .event-tile {
    display: flex;
    align-items: flex-start;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--color-border);
    border-left: 3px solid var(--color-primary);
    border-radius: 2px;
    background: var(--color-card);
    box-shadow: var(--glow-sm);
    transition:
      box-shadow 200ms ease,
      border-color 200ms ease;
  }
  .event-tile:hover {
    border-color: var(--color-primary);
    box-shadow: var(--glow-primary);
  }
  .event-tile__icon {
    --icon-size: 2rem;
    flex-shrink: 0;
    width: var(--icon-size);
    height: var(--icon-size);
    border-radius: 2px;
    background: var(--color-primary);
    color: var(--color-primary-foreground);
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    font-weight: 700;
    text-transform: uppercase;
  }
  .event-tile__body {
    flex: 1;
    min-width: 0;
  }
  .event-tile__title {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    font-weight: 600;
    color: var(--color-foreground);
  }
  .event-tile__desc {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-top: var(--spacing-2xs);
  }
  .event-tile__meta {
    display: flex;
    gap: var(--spacing-xs);
    margin-top: var(--spacing-xs);
  }
  .issue-tile {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--color-border);
    border-left: 3px solid var(--color-muted);
    border-radius: 2px;
    background: var(--color-card);
    cursor: pointer;
    transition:
      box-shadow 200ms ease,
      border-color 200ms ease;
  }
  .issue-tile:hover {
    border-color: var(--color-primary);
    box-shadow: var(--glow-sm);
  }
  .issue-tile[data-lifecycle="active"] {
    border-left-color: var(--color-destructive);
    box-shadow:
      inset 0 0 12px oklch(65% 0.25 25 / 8%),
      var(--glow-sm);
    animation: threat-pulse 1.5s ease-in-out infinite;
  }
  .issue-tile[data-lifecycle="mitigated"] {
    border-left-color: var(--color-warning);
  }
  .issue-tile[data-lifecycle="resolved"] {
    border-left-color: var(--color-success);
    opacity: 0.5;
  }
  @keyframes threat-pulse {
    0%,
    100% {
      border-left-color: var(--color-destructive);
      box-shadow:
        inset 0 0 12px oklch(65% 0.25 25 / 8%),
        var(--glow-sm);
    }
    50% {
      border-left-color: oklch(70% 0.28 25);
      box-shadow:
        inset 0 0 20px oklch(65% 0.25 25 / 15%),
        0 0 18px oklch(65% 0.25 25 / 30%);
    }
  }
