  1→import {
  2→  ChangeDetectionStrategy,
  3→  Component,
  4→  computed,
  5→  effect,
  6→  input,
  7→  output,
  8→  signal,
  9→  untracked,
 10→} from "@angular/core";
 11→import { UpperCasePipe } from "@angular/common";
 12→import { BadgeComponent, ButtonDirective } from "@aspect/ui";
 13→import type { DecisionOption } from "../../core/decision-api.service";
 14→import type { SystemSnapshot } from "../../core/generated/state-changes.types";
 15→import { extractRecRoleId, type RoleCard } from "./role-card.types";
 16→
 17→export interface RoleCardSubmission {
 18→  roleId: string;
 19→  selectedOptions: string[];
 20→  freeText: string;
 21→  targetSystemSelections: Record<string, string>;
 22→}
 23→
 24→@Component({
 25→  selector: "tfc-role-card",
 26→  changeDetection: ChangeDetectionStrategy.OnPush,
 27→  imports: [UpperCasePipe, BadgeComponent, ButtonDirective],
 28→  template: `
 29→    <div
 30→      class="role-card"
 31→      [class.role-card--intel]="card().status === 'intel'"
 32→      [class.role-card--active]="card().status === 'active'"
 33→      [class.role-card--done]="card().status === 'done'"
 34→    >
 35→      <!-- Header -->
 36→      <div class="role-card__header">
 37→        <span class="role-card__role-id">{{ card().roleId | uppercase }}</span>
 38→        <ui-badge
 39→          [variant]="card().status === 'active' ? 'default' : 'secondary'"
 40→        >
 41→          {{ badgeLabel() }}
 42→        </ui-badge>
 43→      </div>
 44→      <div class="role-card__role-label">{{ card().roleLabel }}</div>
 45→
 46→      <!-- Intel -->
 47→      @if (card().intel) {
 48→        <div class="role-card__intel">{{ card().intel }}</div>
 49→      } @else if (card().decision) {
 50→        <div class="role-card__intel role-card__intel--empty">
 51→          No role-specific intel this turn
 52→        </div>
 53→      }
 54→
 55→      <!-- Advisor Recs (CO card only) -->
 56→      @if (card().advisorRecs.length > 0) {
 57→        <div class="role-card__recs">
 58→          <div class="role-card__recs-title">Advisor Recommendations</div>
 59→          @for (rec of card().advisorRecs; track rec.roleId) {
 60→            <div
 61→              class="role-card__rec"
 62→              [class.role-card__rec--pending]="!rec.selection"
 63→            >
 64→              <span class="role-card__rec-role">{{ rec.roleLabel }}:</span>
 65→              @if (rec.selection) {
 66→                <span class="role-card__rec-selection">{{
 67→                  rec.selection
 68→                }}</span>
 69→              } @else {
 70→                <span class="role-card__rec-pending">pending...</span>
 71→              }
 72→            </div>
 73→          }
 74→        </div>
 75→      }
 76→
 77→      <!-- Decision Form (active only) -->
 78→      @if (card().decision && card().status === "active") {
 79→        <div class="role-card__decision">
 80→          @if (
 81→            questionType() === "single_choice" ||
 82→            questionType() === "multi_choice"
 83→          ) {
 84→            @for (option of filteredOptions(); track option.id) {
 85→              <label
 86→                class="role-card__option"
 87→                [class.role-card__option--selected]="isSelected(option.id)"
 88→              >
 89→                <input
 90→                  [type]="
 91→                    questionType() === 'single_choice' ? 'radio' : 'checkbox'
 92→                  "
 93→                  [name]="'role-decision-' + card().roleId"
 94→                  [checked]="isSelected(option.id)"
 95→                  (change)="toggleOption(option)"
 96→                />
 97→                <span>{{ option.label }}</span>
 98→                @if (option.targets_system && isSelected(option.id)) {
 99→                  <select
100→                    class="role-card__system-picker"
101→                    [value]="targetSystemSelections()[option.id] || ''"
102→                    (change)="onSystemSelect(option.id, $event)"
103→                  >
104→                    <option value="">Select system...</option>
105→                    @for (sys of systems(); track sys.system_id) {
106→                      <option [value]="sys.system_id">{{ sys.label }}</option>
107→                    }
108→                  </select>
109→                }
110→              </label>
111→            }
112→          }
113→          @if (questionType() === "free_text") {
114→            <textarea
115→              class="role-card__textarea"
116→              [value]="freeText()"
117→              (input)="onTextInput($event)"
118→              placeholder="Enter your response..."
119→            ></textarea>
120→          }
121→          <div class="role-card__actions">
122→            <button
123→              uiButton
124→              variant="default"
125→              size="sm"
126→              (click)="onSubmit()"
127→              [disabled]="!canSubmit()"
128→            >
129→              Submit
130→            </button>
131→          </div>
132→        </div>
133→      }
134→
135→      <!-- Done State -->
136→      @if (card().status === "done") {
137→        <div class="role-card__done">Selected: {{ doneLabel() }}</div>
138→      }
139→    </div>
140→  `,
141→})
142→export class RoleCardComponent {
143→  readonly card = input.required<RoleCard>();
144→  readonly systems = input<SystemSnapshot[]>([]);
145→  readonly submitted = output<RoleCardSubmission>();
146→
147→  readonly selectedOptions = signal<string[]>([]);
148→  readonly freeText = signal("");
149→  readonly targetSystemSelections = signal<Record<string, string>>({});
150→
151→  private readonly resetOnCardChange = effect(() => {
152→    this.card();
153→    untracked(() => {
154→      this.selectedOptions.set([]);
155→      this.freeText.set("");
156→      this.targetSystemSelections.set({});
157→    });
158→  });
159→
160→  readonly filteredOptions = computed<DecisionOption[]>(() => {
161→    const decision = this.card().decision;
162→    if (!decision) return [];
163→    const playerType = this.card().playerType;
164→    const roleId = this.card().roleId;
165→    if (playerType === "decision_maker") {
166→      return decision.options;
167→    }
168→    // advisor: COMMON options (no role) + own-role options
169→    return decision.options.filter((o) => !o.role || o.role === roleId);
170→  });
171→
172→  readonly badgeLabel = computed<string>(() => {
173→    const status = this.card().status;
174→    if (status === "intel") return "INTEL";
175→    if (status === "active") return "DECISION";
176→    return "DONE";
177→  });
178→
179→  readonly questionType = computed<string>(() => {
180→    return this.card().decision?.question_type ?? "free_text";
181→  });
182→
183→  readonly doneLabel = computed<string>(() => {
184→    const decision = this.card().decision;
185→    if (!decision) return "";
186→    const roleId = this.card().roleId;
187→    const recEntry = Object.entries(decision.recommendations).find(
188→      ([key]) => extractRecRoleId(key) === roleId,
189→    );
190→    const optionId = recEntry?.[1];
191→    if (!optionId) return "";
192→    return decision.options.find((o) => o.id === optionId)?.label ?? optionId;
193→  });
194→
195→  protected isSelected(optionId: string): boolean {
196→    return this.selectedOptions().includes(optionId);
197→  }
198→
199→  protected canSubmit(): boolean {
200→    if (this.questionType() === "free_text") {
201→      return this.freeText().trim().length > 0;
202→    }
203→    if (this.selectedOptions().length === 0) return false;
204→    const opts = this.filteredOptions();
205→    for (const optId of this.selectedOptions()) {
206→      const opt = opts.find((o) => o.id === optId);
207→      if (opt?.targets_system && !this.targetSystemSelections()[optId]) {
208→        return false;
209→      }
210→    }
211→    return true;
212→  }
213→
214→  protected toggleOption(option: DecisionOption): void {
215→    if (this.questionType() === "single_choice") {
216→      this.selectedOptions.set([option.id]);
217→    } else {
218→      const current = this.selectedOptions();
219→      if (current.includes(option.id)) {
220→        this.selectedOptions.set(current.filter((id) => id !== option.id));
